d=deepcopy(D['decisions']['c0564']);d.update(status='duplicate',society_id=boomer['id'],duplicate_of=boomer['id'],reassessed_on=DATE,current_policy_review=True,reason='The shared ordinary Genom boomer/manual-labor model is retained once under c0563; a reboot alone does not establish another material regime.',analysis='2040 supplies extensive manual substitution and continuing human jobs. Those facts are included in the common model, while autonomous-crisis plot differences are not averaged into it.',follow_up='Resolved economic-model overlap; source and continuity caveats retained without an extra point.')
changes.append(change(D,'decisions',d))
for cid,name,scope,desc,values,bounds,facts,assumptions,not_app in [
 ('c0558','Girls’ Last Tour (remnant facilities)','The two living travelers visiting residual automatic facilities, not a durable supplied resident community',
 '''The travelers forage through a megacity containing residual automated maintenance and a depleted fish-production facility. Those systems demonstrate inherited capacity, but the encountered provision is a temporary remnant rather than a continuing arrangement supporting an ordinary human community. Empty infrastructure is not a leisure population. The earlier lore hold is therefore replaced with a completed comparison of the actual travel-and-remnant mechanism.

The comparison uses extremely weak secure support, limited human control of the inherited systems and zero nonworkers centrally for the two-person shared foraging/repair scenario. The possible counts are zero, one or two nonworkers, not fractions of travel time. Useful care for each other counts, while merely moving or resting is not automatically a job. Wide intervals preserve that interpretation. The case stays outside the target because the functioning recipient economy is absent in the depicted encounter, not because a fictional welfare statute could not be found.''',
 (.95,.1,0),([.65,1],[-.8,.65],[0,1]),['Residual automation maintains a sector and a depleted fish facility while two humans travel and forage.'],['The two-person activity point is a discrete scenario, not a time or corpse ratio.','Temporary remnant use is not treated as a durable resident support economy.'],None),
 ('c0577','Space Dandy (Machinia after its final resident)','The residual robotic scrapyard after its last native inhabitant dies; temporary visitors are excluded',
 '''Machinia’s machinery sustains a scrapyard environment whose final native inhabitant dies, after which the system collapses. The late residual setting is not an active community whose absent residents enjoy freedom from work. It is kept as a completed empty-system comparison, while the visitors’ temporary presence is not used to invent permanent recipient citizens or a new human welfare population.

Guarantee and control values are broad analogies for the fragile inherited system: secure continued support is very weak and remaining operation is largely machine-mediated. The nonworking value is inapplicable because no active native civilian person community remains in the selected post-death scope. It is never set to one from extinction. This is an identified population/mechanism difference rather than a demand for more lore. A reconstructed earlier robot civilization could be a separate future lead, but the present comparison does not invent its rights, labor census or surviving members.''',
 (.95,-.8,None),([.7,1],[-1,.1],None),['A robot-maintained scrapyard collapses after its final native inhabitant dies.'],['Residual system coordinates are analogical rather than an inhabited-society claim.','Temporary visitors are excluded from a native participation count.'],{'nonworking':'No active native civilian person community remains in the selected post-death setting; visitors and dead residents are not leisure citizens.'}),
]:
 d=deepcopy(D['decisions'][cid]);a=dict(zip(('guarantees','control','nonworking'),values));b=dict(zip(('guarantees','control','nonworking'),bounds))
 ca=dict(name=name,media=['anime'],scope=scope,axis=a,intervals=b,confidence='low',canon_facts=facts,editorial_assumptions=assumptions,source_ids=d['source_ids'],counted_toward_goal=False)
 if not_app:ca['not_applicable_axes']=not_app
 d.update(status='boundary_case',reassessed_on=DATE,current_policy_review=True,assessment_mode='best_guess',reason='Completed comparison of a residual system rather than a continuing recipient economy; see exact scope.',analysis=desc,follow_up='Completed current-policy comparison; no deep reading required.',comparison_assessment=ca);changes.append(change(D,'decisions',d))
for r in records:changes.extend([change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))])
assert len(records)==27,len(records)
write_revision(22,changes,'Twenty-seven additional anime/game records retained, including Kaiba, System Shock, SOMA, Talos, Destiny and Stray. The ordinary Bubblegum reboot economy is linked without double counting. Residual Girls’ Last Tour/Machinia systems have completed comparisons, with no extinction-to-leisure inference. All retained axes remain complete.')
